import base64,datetime,hashlib,json,os,pathlib,shutil,subprocess,time,traceback,tarfile
B=pathlib.Path('/kaggle/working/unifac-admission-evidence');B.mkdir(exist_ok=False)
W=pathlib.Path('/kaggle/temp/kerotakis-liquid-refusal');W.mkdir(parents=True,exist_ok=False);R=W/'source';START=time.monotonic()
def sha(raw):return hashlib.sha256(raw).hexdigest()
def save(name,value):
 path=B/name;path.parent.mkdir(parents=True,exist_ok=True)
 with path.open('x') as f:json.dump(value,f,indent=2);f.write('\n')
def run(name,args,cwd=W,required=True):
 assert time.monotonic()-START<1650
 with (B/(name+'.stdout')).open('wb') as out,(B/(name+'.stderr')).open('wb') as err:
  result=subprocess.run(args,cwd=cwd,env=env,stdout=out,stderr=err,timeout=max(1,1680-(time.monotonic()-START)))
 save(name+'.json',{'argv':args,'exit_status':result.returncode,'stdout_sha256':sha((B/(name+'.stdout')).read_bytes()),'stderr_sha256':sha((B/(name+'.stderr')).read_bytes())})
 if (pathlib.Path(cwd)/'Cargo.lock').is_file():assert sha((pathlib.Path(cwd)/'Cargo.lock').read_bytes())==PLAN['lock_sha256']
 print(name,result.returncode,flush=True)
 if required:assert result.returncode==0,name
 return result.returncode
save('STARTED.json',{'source':PLAN['source'],'tree':PLAN['tree'],'worker_sha256':sha(pathlib.Path(__file__).read_bytes()),'cpu_only':True});save('frozen-plan.json',PLAN)
try:
 available=int(next(line.split()[1] for line in pathlib.Path('/proc/meminfo').read_text().splitlines() if line.startswith('MemAvailable:')))//1024
 assert available>=6000 and shutil.disk_usage(W).free>=10*1024**3
 if hasattr(os,'sched_getaffinity'):os.sched_setaffinity(0,set(sorted(os.sched_getaffinity(0))[:2]))
 env=dict(os.environ);env.update(CARGO_HOME=str(W/'cargo'),RUSTUP_HOME=str(W/'rustup'),CARGO_BUILD_JOBS='2',CARGO_INCREMENTAL='0',CARGO_TERM_COLOR='never',CARGO_PROFILE_DEV_DEBUG='0',CARGO_PROFILE_TEST_DEBUG='0')
 run('fetch-rustup',['curl','-fsSL','--retry','0','https://sh.rustup.rs','-o',str(W/'rustup-init.sh')]);run('install-rust',['sh',str(W/'rustup-init.sh'),'-y','--profile','minimal','--default-toolchain','1.99.1','--no-modify-path']);env['PATH']=str(W/'cargo/bin')+os.pathsep+env['PATH'];run('compiler',['rustc','--version','--verbose']);run('components',['rustup','component','add','clippy','rustfmt'])
 run('init',['git','init',str(R)]);run('remote',['git','remote','add','origin','https://github.com/CrispStrobe/kerotakis.git'],R)
 run('fetch-baseline',['git','fetch','--depth','1','origin',PLAN['baseline_source']],R);run('checkout-baseline',['git','checkout','--detach','FETCH_HEAD'],R)
 run('workspace-submodules',['git','submodule','update','--init','--recursive','--depth','1'],R);run('workspace-native-source',['bash','tools/fetch-sundials.sh'],R)
 lock=base64.b64decode(PLAN['lock_base64']);assert sha(lock)==PLAN['lock_sha256'];(R/'Cargo.lock').write_bytes(lock);(B/'producer-Cargo.lock').write_bytes(lock)
 assert sha((R/PLAN['baseline_fixture']).read_bytes())==PLAN['baseline_fixture_sha256']
 run('workspace-metadata',['cargo','metadata','--locked','--no-deps','--format-version','1'],R)
 status=run('baseline',PLAN['baseline_command'],R,False);stdout=(B/'baseline.stdout').read_text();stderr=(B/'baseline.stderr').read_text()
 assert status==101 and 'error[E' not in stderr and str(len(PLAN['expected_failing_names']))+' failed' in stdout and '1 passed' in stdout
 for name in PLAN['expected_failing_names']:assert name+' ... FAILED' in stdout,name
 assert PLAN['positive_control']+' ... ok' in stdout
 save('BASELINE-REPRODUCED.json',{'source':PLAN['baseline_source'],'actual_failed_names':PLAN['expected_failing_names'],'positive_control_passed':True})
 run('fetch-fixed',['git','fetch','--depth','1','origin',PLAN['source']],R);run('checkout-fixed',['git','checkout','--detach','FETCH_HEAD'],R)
 assert subprocess.check_output(['git','rev-parse','HEAD^{tree}'],cwd=R,text=True).strip()==PLAN['tree']
 for path,digest in PLAN['source_sha256'].items():assert sha((R/path).read_bytes())==digest,path
 for i,command in enumerate(PLAN['fixed_commands']):run('fixed-'+str(i),command,R)
 raw=(B/'fixed-2.stdout').read_text()
 for name in PLAN['expected_failing_names']+[PLAN['positive_control']]:assert name+' ... ok' in raw,name
 run('source-unchanged',['git','diff','--exit-code','HEAD'],R)
 binaries={}
 with tarfile.open(B/'actual-test-binaries.tar.gz','w:gz') as archive:
  for path in (R/'target/debug/deps').iterdir():
   if path.is_file() and path.stat().st_mode & 0o111:
    with path.open('rb') as f:magic=f.read(4)
    if magic==b'\x7fELF':
     binaries[path.name]=sha(path.read_bytes());archive.add(path,arcname=path.name)
 assert binaries
 save('TEST-BINARY-BINDING.json',{'source':PLAN['source'],'tree':PLAN['tree'],'actual_lock_sha256':sha((R/'Cargo.lock').read_bytes()),'compiled_test_binary_sha256':binaries,'archive_sha256':sha((B/'actual-test-binaries.tar.gz').read_bytes())})
 save('COMPLETED.json',{'source':PLAN['source'],'tree':PLAN['tree'],'baseline_genuine_failures':len(PLAN['expected_failing_names']),'fixed_all_commands_pass':True,'core_consumer_compiles':True,'full_product_or_deployment_acceptance':False,'scientific_catalog_additions':0})
except BaseException as error:
 save('STOPPED.json',{'error_type':type(error).__name__,'error':str(error),'traceback':traceback.format_exc(),'no_auto_retry':True});raise
finally:
 save('SHA256.json',{str(path.relative_to(B)):sha(path.read_bytes()) for path in B.rglob('*') if path.is_file()})
